import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import type { PrimitiveProps } from "../primitives";

const GOLD = "#C8941E";
const BAR = "#8A5F0C";
const BAR_SOFT = "#E3B44A";

// One repeating barcode period, in px. Motion is (frame % period) so it never ends.
const PERIOD = 180;
const PERIOD_BACK = 300;

const barcode = (color: string) =>
  `repeating-linear-gradient(90deg,` +
  ` ${color} 0px, ${color} 30px,` +
  ` transparent 30px, transparent 62px,` +
  ` ${color} 62px, ${color} 76px,` +
  ` transparent 76px, transparent 104px,` +
  ` ${color} 104px, ${color} 142px,` +
  ` transparent 142px, transparent 160px,` +
  ` ${color} 160px, ${color} 170px,` +
  ` transparent 170px, transparent ${PERIOD}px)`;

const barcodeBack = (color: string) =>
  `repeating-linear-gradient(90deg,` +
  ` ${color} 0px, ${color} 56px,` +
  ` transparent 56px, transparent 140px,` +
  ` ${color} 140px, ${color} 178px,` +
  ` transparent 178px, transparent ${PERIOD_BACK}px)`;

const GoldBarcodeDrift: React.FC<PrimitiveProps> = ({ fps }) => {
  const frame = useCurrentFrame();
  const t = frame / fps;

  // Seamless endless scroll: wrap on the gradient period.
  const shift = ((t * (PERIOD / 14)) % PERIOD);
  const shiftBack = ((t * (PERIOD_BACK / 34)) % PERIOD_BACK);

  // Gentle breathing so it never feels static, always periodic.
  const pulse = 0.5 + 0.5 * Math.sin(t * 0.32);

  return (
    <AbsoluteFill style={{ backgroundColor: GOLD, overflow: "hidden" }}>
      {/* soft warm depth across the frame */}
      <AbsoluteFill
        style={{
          backgroundImage: `linear-gradient(160deg, #D9A63A 0%, ${GOLD} 45%, #A8791A 100%)`,
        }}
      />

      {/* wide slow bars behind */}
      <AbsoluteFill
        style={{
          backgroundImage: barcodeBack(BAR_SOFT),
          backgroundPositionX: `${shiftBack}px`,
          opacity: 0.14 + 0.03 * pulse,
        }}
      />

      {/* main barcode */}
      <AbsoluteFill
        style={{
          backgroundImage: barcode(BAR),
          backgroundPositionX: `${shift}px`,
          opacity: 0.2 + 0.05 * pulse,
        }}
      />

      {/* vignette keeps the centre legible for foreground content */}
      <AbsoluteFill
        style={{
          backgroundImage:
            "radial-gradient(ellipse at 50% 45%, rgba(200,148,30,0.45) 0%, rgba(200,148,30,0.10) 45%, rgba(80,52,6,0.42) 100%)",
        }}
      />
    </AbsoluteFill>
  );
};

export default GoldBarcodeDrift;
